<script setup lang="ts">import {Head,useForm} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';const p=defineProps<{placement:any|null}>();const f=useForm({name:p.placement?.name??'',code:p.placement?.code??'',location:p.placement?.location??'',format:p.placement?.format??'banner',width:p.placement?.width??null,height:p.placement?.height??null,max_active_campaigns:p.placement?.max_active_campaigns??1,base_price_cents:p.placement?.base_price_cents??0,pricing_model:p.placement?.pricing_model??'flat',description:p.placement?.description??'',is_active:p.placement?.is_active??true});const save=()=>p.placement?f.put(`/admin/ad-placements/${p.placement.id}`):f.post('/admin/ad-placements');</script><template><Head title="Ad Placement"/><form class="space-y-6 p-6" @submit.prevent="save"><PageHeader :title="placement?'Edit Placement':'Add Placement'" description="Configure inventory location, dimensions, capacity, and pricing."/><div class="grid gap-4 rounded-xl border p-5 md:grid-cols-2"><label>Name<Input v-model="f.name"/></label><label>Code<Input v-model="f.code"/></label><label>Location<Input v-model="f.location"/></label><label>Format<select v-model="f.format" class="h-10 w-full rounded-md border bg-background px-3"><option>banner</option><option>card</option><option>hero</option><option>native</option><option>video</option></select></label><label>Width<Input v-model="f.width" type="number"/></label><label>Height<Input v-model="f.height" type="number"/></label><label>Maximum active campaigns<Input v-model="f.max_active_campaigns" type="number"/></label><label>Base price (cents)<Input v-model="f.base_price_cents" type="number"/></label><label>Pricing model<select v-model="f.pricing_model" class="h-10 w-full rounded-md border bg-background px-3"><option>flat</option><option>cpm</option><option>cpc</option><option>sponsorship</option></select></label><label class="flex items-center gap-2"><input v-model="f.is_active" type="checkbox"/>Active</label><label class="md:col-span-2">Description<textarea v-model="f.description" class="min-h-24 w-full rounded-md border bg-background p-3"/></label></div><Button :disabled="f.processing">Save Placement</Button></form></template>